def build_messages(system: str, tools: str, user: str) -> list[dict]:
    # static first (cacheable prefix), variable last
    return [
        {"role": "system", "content": system},
        {"role": "system", "content": tools},
        {"role": "user", "content": user},
    ]

def estimate_loop_cost(prefix_tokens, fresh_tokens, steps, in_rate, cached_rate) -> float:
    total = 0.0
    for i in range(steps):
        # step 0 misses (full rate); every later step hits (cached rate)
        rate = in_rate if i == 0 else cached_rate
        prefix_cost = (prefix_tokens / 1000) * rate
        fresh_cost = (fresh_tokens / 1000) * in_rate
        total += prefix_cost + fresh_cost
    return round(total, 5)

